//! Unit tests for the allocator's contracts. Numeric parity with the Python
//! reference on larger tables lives in `tests/integration/allocation_parity.rs`
//! against fixtures generated by the Python tool.

use std::collections::BTreeMap;

use super::*;
use crate::sensitivity::{SensitivityMethod, SensitivityResult, SensitivityTable};

fn bits(value: u32) -> BitWidth {
    BitWidth::new(value).expect("test bit widths are valid")
}

/// A bf16-reference result: KL falls as bits rise.
fn result(module_name: &str, parameters: u64, kl_by_bits: &[(u32, f64)]) -> SensitivityResult {
    SensitivityResult {
        module_name: module_name.to_owned(),
        kl_divergence_by_bit_width: kl_by_bits
            .iter()
            .map(|(bit_count, kl)| (bits(*bit_count), *kl))
            .collect(),
        logical_parameter_count: parameters,
    }
}

fn table(results: Vec<SensitivityResult>) -> SensitivityTable {
    SensitivityTable {
        method: SensitivityMethod::ExactBfloat16Reference,
        results,
    }
}

fn constraints_without_block_rules(target: f64) -> AllocationConstraints {
    AllocationConstraints {
        protect_boundary_blocks: false,
        floor_components_per_block: 0,
        maximum_low_bit_block_run: 0,
        ..AllocationConstraints::defaults_for_target(target)
    }
}

#[test]
fn should_return_an_empty_result_for_an_empty_table() {
    let allocation = optimize_mixed_precision(
        &table(Vec::new()),
        &AllocationConstraints::defaults_for_target(4.5),
    )
    .expect("an empty table allocates trivially");

    assert!(allocation.decisions.is_empty());
    assert_eq!(allocation.achieved_bits_per_weight, 0.0);
}

#[test]
fn should_upgrade_the_most_efficient_module_first_until_the_target_is_met() {
    // Equal sizes; `sensitive` gains far more from 4→8 than `robust`, so at
    // a 6.0 target exactly one of the two is upgraded and it is `sensitive`.
    let sensitivity_table = table(vec![
        result("model.layers.5.mlp.up_proj", 1000, &[(4, 1.0), (8, 0.1)]),
        result("model.layers.6.mlp.up_proj", 1000, &[(4, 0.2), (8, 0.1)]),
    ]);

    let allocation =
        optimize_mixed_precision(&sensitivity_table, &constraints_without_block_rules(6.0))
            .expect("allocation should succeed");

    let decision_for = |name: &str| {
        allocation
            .decisions
            .iter()
            .find(|decision| decision.module_name == name)
            .expect("every module gets a decision")
            .bit_width
    };
    assert_eq!(decision_for("model.layers.5.mlp.up_proj"), bits(8));
    assert_eq!(decision_for("model.layers.6.mlp.up_proj"), bits(4));
    assert_eq!(allocation.achieved_bits_per_weight, 6.0);
}

#[test]
fn should_treat_the_target_as_a_floor_and_accept_discrete_overshoot() {
    let sensitivity_table = table(vec![
        result("model.layers.5.mlp.up_proj", 1000, &[(4, 1.0), (8, 0.1)]),
        result("model.layers.6.mlp.up_proj", 1000, &[(4, 0.2), (8, 0.1)]),
    ]);

    let allocation =
        optimize_mixed_precision(&sensitivity_table, &constraints_without_block_rules(5.0))
            .expect("allocation should succeed");

    // One upgrade lands at 6.0, above the 5.0 target; never below it.
    assert!(allocation.achieved_bits_per_weight >= 5.0);
}

#[test]
fn should_upgrade_protected_modules_before_unprotected_ones_of_equal_efficiency() {
    let sensitivity_table = table(vec![
        result("lm_head", 1000, &[(4, 0.5), (8, 0.1)]),
        result("model.layers.6.mlp.up_proj", 1000, &[(4, 0.5), (8, 0.1)]),
    ]);

    let allocation =
        optimize_mixed_precision(&sensitivity_table, &constraints_without_block_rules(6.0))
            .expect("allocation should succeed");

    let head_decision = allocation
        .decisions
        .iter()
        .find(|decision| decision.module_name == "lm_head")
        .expect("the head gets a decision");
    assert_eq!(head_decision.bit_width, bits(8));
}

#[test]
fn should_treat_non_finite_measurements_as_maximally_sensitive() {
    let sensitivity_table = table(vec![
        result(
            "model.layers.5.mlp.up_proj",
            1000,
            &[(4, f64::NAN), (8, 0.1)],
        ),
        result("model.layers.6.mlp.up_proj", 1000, &[(4, 0.9), (8, 0.1)]),
    ]);

    let allocation =
        optimize_mixed_precision(&sensitivity_table, &constraints_without_block_rules(6.0))
            .expect("allocation should succeed");

    assert_eq!(
        allocation.non_finite_module_names,
        vec!["model.layers.5.mlp.up_proj".to_owned()]
    );
    let nan_decision = allocation
        .decisions
        .iter()
        .find(|decision| decision.module_name == "model.layers.5.mlp.up_proj")
        .expect("decision present");
    assert_eq!(nan_decision.bit_width, bits(8));
}

#[test]
fn should_leave_every_module_at_the_minimum_when_no_upgrade_has_benefit() {
    let sensitivity_table = table(vec![result(
        "model.layers.5.mlp.up_proj",
        1000,
        &[(4, 0.1), (8, 0.1)],
    )]);

    let allocation =
        optimize_mixed_precision(&sensitivity_table, &constraints_without_block_rules(8.0))
            .expect("allocation should succeed");

    assert_eq!(allocation.decisions[0].bit_width, bits(4));
}

#[test]
fn should_detect_the_uniform_reference_sign_convention() {
    // Uniform-4-bit reference: KL at 4 is ~0 and KL at 8 is the benefit.
    let uniform_result = result("m", 1, &[(4, 1e-18), (8, 0.3)]);
    let bf16_result = result("m", 1, &[(4, 0.3), (8, 0.05)]);

    assert_eq!(
        knapsack::kl_reduction(&uniform_result, bits(4), bits(8)),
        0.3 - 1e-18
    );
    assert_eq!(knapsack::kl_reduction(&bf16_result, bits(4), bits(8)), 0.25);
}

#[test]
fn should_reserve_two_floor_slots_for_attention_in_a_full_attention_block() {
    // Feed-forward projections out-rank attention on raw KL; the floor must
    // still promote two attention components.
    let results = vec![
        result(
            "model.layers.23.self_attn.q_proj",
            1,
            &[(4, 0.10), (8, 0.0)],
        ),
        result(
            "model.layers.23.self_attn.k_proj",
            1,
            &[(4, 0.09), (8, 0.0)],
        ),
        result(
            "model.layers.23.self_attn.v_proj",
            1,
            &[(4, 0.08), (8, 0.0)],
        ),
        result(
            "model.layers.23.self_attn.o_proj",
            1,
            &[(4, 0.07), (8, 0.0)],
        ),
        result("model.layers.23.mlp.up_proj", 1, &[(4, 0.90), (8, 0.0)]),
        result("model.layers.23.mlp.down_proj", 1, &[(4, 0.80), (8, 0.0)]),
    ];
    let mut allocation: BTreeMap<String, BitWidth> = results
        .iter()
        .map(|entry| (entry.module_name.clone(), bits(4)))
        .collect();

    let upgrade_count =
        block_floor::apply_block_aware_floor(&mut allocation, &results, bits(4), bits(8), 2);

    assert_eq!(upgrade_count, 2);
    assert_eq!(allocation["model.layers.23.self_attn.q_proj"], bits(8));
    assert_eq!(allocation["model.layers.23.self_attn.k_proj"], bits(8));
    assert_eq!(allocation["model.layers.23.mlp.up_proj"], bits(4));
}

#[test]
fn should_cap_the_floor_at_one_for_a_two_linear_block() {
    let results = vec![
        result("model.layers.3.mixer.in_proj", 1, &[(4, 0.5), (8, 0.0)]),
        result("model.layers.3.mixer.out_proj", 1, &[(4, 0.4), (8, 0.0)]),
    ];
    let mut allocation: BTreeMap<String, BitWidth> = results
        .iter()
        .map(|entry| (entry.module_name.clone(), bits(4)))
        .collect();

    let upgrade_count =
        block_floor::apply_block_aware_floor(&mut allocation, &results, bits(4), bits(8), 2);

    assert_eq!(upgrade_count, 1);
}

#[test]
fn should_break_a_run_of_low_bit_blocks_longer_than_the_limit() {
    // Five consecutive blocks with both components at 4 bits, limit 3.
    let mut results = Vec::new();
    for block_index in 0..5 {
        results.push(result(
            &format!("model.layers.{block_index}.mlp.up_proj"),
            1,
            &[(4, 0.5), (8, 0.0)],
        ));
        results.push(result(
            &format!("model.layers.{block_index}.mlp.down_proj"),
            1,
            &[(4, 0.1), (8, 0.0)],
        ));
    }
    let mut allocation: BTreeMap<String, BitWidth> = results
        .iter()
        .map(|entry| (entry.module_name.clone(), bits(4)))
        .collect();

    let upgrade_count =
        block_run_guard::enforce_block_run_limit(&mut allocation, &results, bits(4), bits(8), 3);

    // Stride 3 over a run of 5 visits blocks 0 and 3; the most sensitive
    // low-bit component (up_proj) in each is promoted.
    assert_eq!(upgrade_count, 2);
    assert_eq!(allocation["model.layers.0.mlp.up_proj"], bits(8));
    assert_eq!(allocation["model.layers.3.mlp.up_proj"], bits(8));
}

#[test]
fn should_match_module_paths_by_suffix_after_stripping_the_model_prefix() {
    let allocation = AllocationResult {
        decisions: vec![ModuleQuantizationDecision {
            module_name: "model.layers.0.mlp.up_proj".to_owned(),
            bit_width: bits(8),
            group_size: GroupSize::new(64).expect("valid"),
            logical_parameter_count: 1,
        }],
        target_bits_per_weight: 8.0,
        achieved_bits_per_weight: 8.0,
        module_count_at_highest_width: 1,
        module_count_at_lowest_width: 0,
        total_logical_parameter_count: 1,
        estimated_weight_bytes: 1,
        floor_upgrade_count: 0,
        run_guard_upgrade_count: 0,
        non_finite_module_names: Vec::new(),
    };

    let predicate = QuantizationPredicate::from_allocation(&allocation, None);

    assert_eq!(
        predicate.decision_for("layers.0.mlp.up_proj"),
        predicate::QuantizationDecisionForModule::Quantize {
            bit_width: bits(8),
            group_size: GroupSize::new(64).expect("valid"),
        }
    );
    // Unmatched modules default to the allocation's highest width.
    assert_eq!(
        predicate.decision_for("model.embed_tokens"),
        predicate::QuantizationDecisionForModule::Quantize {
            bit_width: bits(8),
            group_size: GroupSize::new(64).expect("valid"),
        }
    );
}

#[test]
fn should_emit_keep_bfloat16_for_the_lossless_tier() {
    let allocation = AllocationResult {
        decisions: vec![ModuleQuantizationDecision {
            module_name: "lm_head".to_owned(),
            bit_width: bits(16),
            group_size: GroupSize::new(64).expect("valid"),
            logical_parameter_count: 1,
        }],
        target_bits_per_weight: 16.0,
        achieved_bits_per_weight: 16.0,
        module_count_at_highest_width: 1,
        module_count_at_lowest_width: 0,
        total_logical_parameter_count: 1,
        estimated_weight_bytes: 2,
        floor_upgrade_count: 0,
        run_guard_upgrade_count: 0,
        non_finite_module_names: Vec::new(),
    };

    let predicate = QuantizationPredicate::from_allocation(&allocation, None);

    assert_eq!(
        predicate.decision_for("lm_head"),
        predicate::QuantizationDecisionForModule::KeepBfloat16
    );
}

#[test]
fn should_surface_an_overshoot_note_when_the_floor_pushes_past_the_target() {
    let allocation = AllocationResult {
        decisions: Vec::new(),
        target_bits_per_weight: 4.0,
        achieved_bits_per_weight: 5.3,
        module_count_at_highest_width: 0,
        module_count_at_lowest_width: 0,
        total_logical_parameter_count: 0,
        estimated_weight_bytes: 0,
        floor_upgrade_count: 0,
        run_guard_upgrade_count: 0,
        non_finite_module_names: Vec::new(),
    };

    let note = allocation.overshoot_note(2);

    assert!(note.is_some_and(|text| text.contains("+32%")));
}
